#!/usr/bin/env python3
"""Check SSH host certificates for all servers in the inventory.

Verifies each certificate is a valid host certificate signed by the CA,
checks revocation state against the KRL, prints a per-server summary and
exits 0 only if all active certificates pass and revoked ones are identified.
"""
import re
import subprocess
import sys

INVENTORY = "/app/inventory.txt"
CADIR = "/app/ssh-ca"
CA_PUB = CADIR + "/ca.pub"
KRL = CADIR + "/revoked.krl"
REVOKED_SERVERS = {"db2"}


def run(cmd):
    return subprocess.run(cmd, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, text=True)


def ca_fingerprint():
    r = run(["ssh-keygen", "-lf", CA_PUB])
    if r.returncode != 0:
        return None
    return r.stdout.split()[1]


def parse_cert(text):
    d = {"principals": []}
    in_principals = False
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if s.startswith("Type:"):
            d["type"] = s.split(":", 1)[1].strip()
            in_principals = False
        elif s.startswith("Signing CA:"):
            parts = s.split()
            d["signing_ca"] = parts[3] if len(parts) >= 4 else None
            in_principals = False
        elif s.startswith("Key ID:"):
            m = re.search(r'"([^"]*)"', s)
            d["key_id"] = m.group(1) if m else ""
            in_principals = False
        elif s.startswith("Serial:"):
            d["serial"] = s.split(":", 1)[1].strip()
            in_principals = False
        elif s.startswith("Valid:"):
            m = re.search(r"from (\S+) to (\S+)", s)
            if m:
                d["valid_from"] = m.group(1)
                d["valid_to"] = m.group(2)
            in_principals = False
        elif s.startswith("Principals:"):
            in_principals = True
        elif s.startswith("Critical Options:") or s.startswith("Extensions:"):
            in_principals = False
        elif in_principals:
            d["principals"].append(s)
    return d


def is_revoked(path):
    r = run(["ssh-keygen", "-Qf", KRL, path])
    return "REVOKED" in r.stdout


def main():
    servers = []
    with open(INVENTORY) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            name, fqdn, ip, ktype = line.split(",")
            servers.append((name, fqdn, ip, ktype))

    ca_fp = ca_fingerprint()
    if not ca_fp:
        print("ERROR: could not read CA public key")
        return 1

    all_ok = True
    for name, fqdn, ip, ktype in servers:
        cert = "{}/{}_host_key-cert.pub".format(CADIR, name)
        expected_revoked = name in REVOKED_SERVERS
        problems = []
        info = {}
        r = run(["ssh-keygen", "-Lf", cert])
        if r.returncode != 0:
            problems.append("cannot inspect certificate")
        else:
            info = parse_cert(r.stdout)
            if "host certificate" not in info.get("type", ""):
                problems.append("not a host certificate")
            if info.get("signing_ca") != ca_fp:
                problems.append("not signed by CA")
            if info.get("key_id") != name:
                problems.append("identity mismatch")
            for p in (fqdn, name, ip):
                if p not in info["principals"]:
                    problems.append("missing principal " + p)
        revoked = is_revoked(cert)
        if revoked and not expected_revoked:
            problems.append("unexpectedly revoked")
        if expected_revoked and not revoked:
            problems.append("should be revoked but is not")
        ok = not problems
        all_ok = all_ok and ok
        expires = info.get("valid_to", "?")[:10]
        prins = ",".join(info.get("principals", []))
        if revoked:
            status = "REVOKED"
        elif ok:
            status = "OK"
        else:
            status = "FAIL (" + "; ".join(problems) + ")"
        print("{}: principals=[{}] expires={} status={}".format(
            name, prins, expires, status))

    print("Overall: " + ("PASS" if all_ok else "FAIL"))
    return 0 if all_ok else 1


if __name__ == "__main__":
    sys.exit(main())
EOF
